int pk_gibb_datacenter_parse(const uint8_t *buf, uint64_t bit_len, pk_gibb_datacenter_result_t *out) {
  pk_gibb_datacenter_result_t zero = {0};
  *out = zero;
  return pk_gibb_datacenter_parse_core(buf, bit_len, out);
}

const char *pk_gibb_datacenter_reason_str(uint16_t reason) {
  switch (reason) {
  case 1: return "out of bounds";
  case 2: return "max depth exceeded";
  case 3: return "no matching select arm";
  case 4: return "out of region bounds";
  case 5: return "region out of bounds";
  case 6: return "region not exhausted";
  default: return "";
  }
}
